const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const root = '/bench/repo';
const internalRoot = path.join(root, 'internal');
const declRe = /^func (?:\(\s*(\*?\w+)\s+\*?(\w+)\s*\)\s*)?(\w+)\(/;

const symbols = [];
function walk(dir) {
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walk(p);
    else if (ent.name.endsWith('.go') && !ent.name.endsWith('_test.go')) {
      const rel = path.relative(root, p);
      const content = fs.readFileSync(p, 'utf8');
      for (const m of content.matchAll(/^func (?:\(\s*(\*?\w+)\s+\*?(\w+)\s*\)\s*)?(\w+)\(/gm)) {
        const [, recvPtr, recvType, name] = m;
        let sym = name;
        if (recvType) sym = `${recvPtr || ''}${recvType}.${name}`.replace(/^\*/, '(*');
        symbols.push({ sym, rel, name, recvType });
      }
    }
  }
}
walk(internalRoot);
console.log('declarations', symbols.length);

function countRefs(name) {
  let out = '';
  try {
    out = execSync(`grep -r -n --include='*.go' -w '${name}' '${root}'`, { encoding: 'utf8', maxBuffer: 50*1024*1024 });
  } catch (e) {
    if (e.stdout) out = e.stdout.toString();
    else return { count: 0, files: 0 };
  }
  const files = new Set();
  let count = 0;
  for (const line of out.split('\n')) {
    if (!line) continue;
    const fp = line.split(':')[0];
    if (fp.includes('/proto/gen/')) continue;
    count++;
    files.add(fp);
  }
  return { count, files: files.size };
}

const exported = symbols.filter(s => s.name[0] === s.name[0].toUpperCase() && s.name[0] !== s.name[0].toLowerCase());
const results = exported.map(s => ({ ...s, ...countRefs(s.name) }));
results.sort((a,b) => b.count - a.count || b.files - a.files);
console.log('\nTop 30:');
for (const r of results.slice(0,30)) {
  console.log(`${String(r.count).padStart(4)} files=${String(r.files).padStart(3)}  ${r.sym.padEnd(45)} ${r.rel}`);
}
NODE

