use strict; use warnings;
my $root = "/bench/repo";

# map import path suffix -> package name from internal dirs
my %pkgfiles;
for my $path (glob("$root/internal/**/*.go")) {
  next if $path =~ /_test\.go$/;
  open my $fh, "<", $path or next;
  my ($pkg, $rel);
  $rel = $path; $rel =~ s/^\Q$root\E\///;
  while (<$fh>) {
    if (/^package\s+(\w+)/) { $pkg = $1; last; }
  }
  close $fh;
  push @{ $pkgfiles{$pkg} }, $rel;
}

# collect exported funcs per file
my @syms;
for my $path (glob("$root/internal/**/*.go")) {
  next if $path =~ /_test\.go$/;
  open my $fh, "<", $path or next;
  my ($pkg, $rel) = ("", $path); $rel =~ s/^\Q$root\E\///;
  while (<$fh>) { $pkg = $1 if /^package\s+(\w+)/; }
  seek $fh, 0, 0;
  while (<$fh>) {
    if (/^func\s+\(([^)]+)\)\s+([A-Z]\w*)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      $recv =~ s/^\*?(\w+).*/$1/;
      push @syms, { pkg=>$pkg, kind=>"method", recv=>$recv, name=>$name, rel=>$rel,
        import=>"github.com/usememos/memos/internal/" . ($rel =~ m{internal/(.+)/[^/]+\.go} ? $1 : "") };
    } elsif (/^func\s+([A-Z]\w*)\s*\(/) {
      push @syms, { pkg=>$pkg, kind=>"func", name=>$1, rel=>$rel,
        import=>"github.com/usememos/memos/internal/" . ($rel =~ m{internal/(.+)/[^/]+\.go} ? $1 : "") };
    }
  }
  close $fh;
}

# read all go files once
my @files = glob("$root/{cmd,internal,server,store}/**/*.go");
my %contents;
for my $f (@files) {
  next if $f =~ /\/proto\/gen\//;
  open my $fh, "<", $f or next; local $/; $contents{$f} = <$fh>; close $fh;
}

sub count_pkg_func {
  my ($pkg, $name) = @_;
  my $pat = qr/\b\Q$pkg\E\.\Q$name\E\s*\(/;
  my $c = 0;
  for my $f (keys %contents) {
    next if $f =~ /\Q$name\E\.go$/ && $contents{$f} =~ /^func\s+\Q$name\E\s*\(/m; # skip def only? still count other refs in same file
    while ($contents{$f} =~ /$pat/g) { $c++ }
  }
  return $c;
}

# Also count via last import segment when packages imported with path
sub count_import_func {
  my ($imp_suffix, $name) = @_;
  my $c = 0;
  for my $f (keys %contents) {
    # find local alias for import ending with imp_suffix
    my $alias = "";
    if ($contents{$f} =~ /import\s*\((.*?)\)/s) {
      my $block = $1;
      for my $line (split /\n/, $block) {
        if ($line =~ /(?:\w+\s+)?"github\.com\/usememos\/memos\/internal\/\Q$imp_suffix\E"/) {
          ($alias) = $line =~ /^(\w+)\s+/;
          $alias = $1 if $alias;
          $alias = (split /\//, $imp_suffix)[-1] unless $alias;
        }
      }
    }
    if ($contents{$f} =~ /^\s*import\s+\w+\s+"github\.com\/usememos\/memos\/internal\/\Q$imp_suffix\E"/m) {
      my ($a) = $contents{$f} =~ /import\s+(\w+)\s+"github\.com\/usememos\/memos\/internal\/\Q$imp_suffix\E"/;
      $alias = $a if $a;
    }
    my $pkg = $alias || (split /\//, $imp_suffix)[-1];
    my $pat = qr/\b\Q$pkg\E\.\Q$name\E\s*\(/;
    while ($contents{$f} =~ /$pat/g) { $c++ }
  }
  return $c;
}

my @results;
for my $s (@syms) {
  next if $s->{kind} eq "method"; # handle methods separately
  my $imp = $s->{rel}; $imp =~ s{^internal/}{}; $imp =~ s{/[^/]+$}{};
  my $c = count_pkg_func($s->{pkg}, $s->{name});
  # also common import aliases differ - scan all aliases for this import path
  my $path = "github.com/usememos/memos/internal/$imp";
  my $c2 = 0;
  for my $f (keys %contents) {
    next unless index($contents{$f}, $path) >= 0;
    my @aliases;
    while ($contents{$f} =~ /(?:\b(\w+)\s+)?"(\Q$path\E)"/g) {
      my ($a,$p) = ($1,$2);
      push @aliases, $a || (split /\//, $imp)[-1];
    }
    @aliases = ($s->{pkg}) unless @aliases;
    for my $a (@aliases) {
      my $pat = qr/\b\Q$a\E\.\Q$s->{name}\E\s*\(/;
      while ($contents{$f} =~ /$pat/g) { $c2++ }
    }
  }
  my $sym = $s->{name};
  push @results, [$c2, $sym, $s->{rel}];
}

# methods with unique enough names
for my $s (@syms) {
  next if $s->{kind} ne "method";
  my $name = $s->{name};
  next if $name =~ /^(Validate|Render|Compile|Parse|Kind|Next|Field|Start|Stop|Register|Send|Format|Len|Less|Swap)$/;
  my $c = 0;
  my $pat = qr/\.\Q$name\E\s*\(/;
  for my $f (keys %contents) {
    next if $f =~ /\Q$s->{rel}\E$/;
    while ($contents{$f} =~ /$pat/g) { $c++ }
  }
  push @results, [$c, "$s->{recv}.$name", $s->{rel}] if $c > 0;
}

@results = sort { $b->[0] <=> $a->[0] || $a->[1] cmp $b->[1] } @results;
print "Top 30 package funcs:\n";
my $n=0;
for my $r (@results) {
  printf "%4d  %-30s %s\n", $r->[0], $r->[1], $r->[2];
  last if ++$n >= 30;
}
'

